/**
 * Заглушка платформенного `sdk` для локальных тестов хендлеров.
 * В облаке этот модуль подставляет сама платформа; здесь он нужен,
 * чтобы проверять ровно тот код, который уедет в Telegram.
 */
export const calls = [];

export class BotApiError extends Error {
  constructor(method, code, description) {
    super(`${method} failed [${code}]: ${description}`);
    this.method = method;
    this.code = code;
    this.description = description;
  }
}

export class EndpointError extends Error {
  constructor(description, parameters) {
    super(description);
    this.parameters = parameters || {};
  }
}

const replies = {
  getMe: () => ({ id: 1, username: 'example_bot', first_name: 'Chess' }),
};

export const api = new Proxy(
  {},
  {
    get(_t, method) {
      return async (params) => {
        calls.push({ method: String(method), params });
        if (replies[method]) return replies[method](params);
        return { ok: true, message_id: 1 };
      };
    },
  },
);

export const fetch = async () => ({ ok: true, status: 200, json: async () => ({}), text: async () => '' });

export class InputFile {
  constructor(bytes, name, opts) {
    this.bytes = bytes;
    this.name = name;
    this.type = opts?.type;
  }
}

export function resetCalls() {
  calls.length = 0;
}
